def project_from_markers(markers, grid_rows=8, grid_cols=8):
    """Return set of cells that lie on rays from markers"""
    projected = set()

    # For each marker, project horizontally left/right and vertically up/down
    for r, c in markers:
        # Left
        for cc in range(c-1, -1, -1):
            if (r, cc) in markers:
                break
            projected.add((r, cc))
        # Right
        for cc in range(c+1, grid_cols):
            if (r, cc) in markers:
                break
            projected.add((r, cc))
        # Up
        for rr in range(r-1, -1, -1):
            if (rr, c) in markers:
                break
            projected.add((rr, c))
        # Down
        for rr in range(r+1, grid_rows):
            if (rr, c) in markers:
                break
            projected.add((rr, c))

    return projected

